#!/bin/sh
# Project: cracking-rosetta | Phase: 3 - upstream seed data
# Refresh vendor/cynosureprime/ from GitHub and record the commit it came from.
# POSIX sh; needs curl and python3. Run from anywhere.
# Generated by Claude Opus 5 on 2026-08-29
set -e

root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
dest="$root/vendor/cynosureprime"
repo=Cynosureprime/hashpipe
base=https://raw.githubusercontent.com/$repo

mkdir -p "$dest"
for f in HASH_TYPES.md john_map.h; do
    out="$dest/$(echo "$f" | sed 's/^HASH_TYPES.md$/hashpipe-HASH_TYPES.md/')"
    printf -- '- fetching %s\n' "$f" >&2
    curl -fsS -m 60 -o "$out" "$base/HEAD/$f"
done

sha=$(curl -fsS -m 30 "https://api.github.com/repos/$repo/commits?per_page=1" \
      | python3 -c 'import json,sys; print(json.load(sys.stdin)[0]["sha"])')

printf -- '- %s is now at %s\n' "$repo" "$sha" >&2
printf -- '- Update the commit and Fetched columns in %s/PROVENANCE.md,\n' "$dest" >&2
printf -- '- then re-run the extractors and tools/seed-upstream.pl.\n' >&2
